import pandas as pd
import numpy as np
import re

def parse_notes(notes):
    # Default values
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if pd.isna(notes):
        return items, adj_pct, fee, waive

    parts = str(notes).split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if '=' not in part:
            continue
        key, val = part.split('=', 1)
        key = key.strip().lower()
        val = val.strip()

        if key == 'items':
            try:
                items = int(val)
            except ValueError:
                pass
        elif key == 'adj':
            # Val should be like -5.62% or +12.03%
            # Let's remove '%' from the end
            val_clean = val
            if val_clean.endswith('%'):
                val_clean = val_clean[:-1]
            try:
                # Parse as float and divide by 100
                adj_pct = float(val_clean) / 100.0
            except ValueError:
                pass
        elif key == 'fee':
            try:
                fee = float(val)
            except ValueError:
                pass
        elif key == 'waive':
            if val.lower() == 'true':
                waive = True

    return items, adj_pct, fee, waive

# Test on unique notes values
df = pd.read_csv('/app/dataset/data.csv')
unique_notes = df['notes'].dropna().unique()

print("Testing notes parser on some samples:")
for val in unique_notes[:30]:
    items, adj_pct, fee, waive = parse_notes(val)
    print(f"Original: {repr(val):<60} -> items={items}, adj_pct={adj_pct}, fee={fee}, waive={waive}")

